def load_crops(crops_dir: Path) -> dict[str, dict[str, np.ndarray]]:
    parts: dict[str, list[dict[str, np.ndarray]]] = {}
    for path in sorted(crops_dir.glob("*.npz")):
        with np.load(path) as f:
            if len(f["label"]) == 0:
                continue
            embryo = str(f["embryo"])
            parts.setdefault(embryo, []).append(
                {k: f[k] for k in ("crops", "label", "kind")}
                | {"movie": np.full(len(f["label"]), path.stem)}
            )
    return {e: {k: np.concatenate([p[k] for p in ps]) for k in ps[0]} for e, ps in parts.items()}

def _sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1 << 20), b""):
            digest.update(block)
    return digest.hexdigest()
